import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("invalid input")
    match = re.fullmatch(r'(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', s)
    if match is None:
        raise ValueError("malformed duration")
    d, h, m, sec = match.groups()
    if d is None and h is None and m is None and sec is None:
        raise ValueError("malformed duration")
    total = 0
    if d is not None:
        total += int(d) * 86400
    if h is not None:
        total += int(h) * 3600
    if m is not None:
        total += int(m) * 60
    if sec is not None:
        total += int(sec)
    return total
