def eval_rpn(tokens: list[str]) -> int:
    stack: list[int] = []
    for tok in tokens:
        if tok in ("+", "-", "*", "/"):
            b = stack.pop()
            a = stack.pop()
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                sign = -1 if ((a < 0) != (b < 0)) else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(tok))
    return stack.pop()
