def calc(expr: str) -> float:
    s = expr
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        return s[i] if i < n else ''

    def consume(ch=None):
        nonlocal i
        skip()
        if i >= n:
            raise ValueError("Unexpected end of expression")
        c = s[i]
        if ch is not None and c != ch:
            raise ValueError(f"Expected {ch!r}, got {c!r}")
        i += 1
        return c

    def parse_primary():
        skip()
        if peek() == '(':
            i += 1
            val = parse_expr()
            consume(')')
            return val
        start = i
        seen_digit = False
        seen_dot = False
        while i < n:
            c = s[i]
            if c.isdigit():
                seen_digit = True
                i += 1
            elif c == '.' and not seen_dot:
                seen_dot = True
                i += 1
            else:
                break
        txt = s[start:i]
        if not txt or not any(ch.isdigit() for ch in txt):
            raise ValueError("Invalid number")
        return float(txt)

    def parse_unary():
        skip()
        if peek() == '-':
            i += 1
            return -parse_unary()
        if peek() == '+':
            i += 1
            return parse_unary()
        return parse_primary()

    def parse_term():
        val = parse_unary()
        while True:
            skip()
            if peek() == '*':
                i += 1
                val = val * parse_unary()
            elif peek() == '/':
                i += 1
                val = val / parse_unary()
            else:
                return val

    def parse_expr():
        val = parse_term()
        while True:
            skip()
            if peek() == '+':
                i += 1
                val = val + parse_term()
            elif peek() == '-':
                i += 1
                val = val - parse_term()
            else:
                return val

    result = parse_expr()
    skip()
    if i != n:
        raise ValueError("Unexpected character")
    return result
