from collections import defaultdict

def sliding_median(nums: list[int], k: int) -> list[float]:
    n = len(nums)
    if k <= 0 or k > n:
        return []

    left = []   # max-heap (negated)
    right = []  # min-heap
    left_size = 0
    right_size = 0
    delayed = defaultdict(int)

    def prune_left():
        while left:
            x = -left[0]
            if delayed[x] > 0:
                delayed[x] -= 1
                heapq.heappop(left)
            else:
                break

    def prune_right():
        while right:
            x = right[0]
            if delayed[x] > 0:
                delayed[x] -= 1
                heapq.heappop(right)
            else:
                break

    def add(x):
        nonlocal left_size, right_size
        prune_left()
        prune_right()
        if left and x <= -left[0]:
            heapq.heappush(left, -x)
            left_size += 1
        else:
            heapq.heappush(right, x)
            right_size += 1
        if left_size > right_size + 1:
            prune_left()
            x = -heapq.heappop(left)
            left_size -= 1
            heapq.heappush(right, x)
            right_size += 1
        elif right_size > left_size:
            prune_right()
            x = heapq.heappop(right)
            right_size -= 1
            heapq.heappush(left, -x)
            left_size += 1

    def remove(x):
        nonlocal left_size, right_size
        prune_left()
        prune_right()
        if left and x <= -left[0]:
            left_size -= 1
        else:
            right_size -= 1
        delayed[x] += 1

    result = []
    for i in range(n):
        add(nums[i])
        if i >= k:
            remove(nums[i - k])
        if i >= k - 1:
            prune_left()
            prune_right()
            if k % 2 == 1:
                result.append(float(-left[0]))
            else:
                result.append((-left[0] + right[0]) / 2.0)
    return result
